// Extrai dados do item
const body = $input.first().json.body || $input.first().json;
const item_id = body.item_id || body.id;
const video = body.video || body;
const title = video.title || video.query || 'produto viral';
const platform = video.platform || 'tiktok';

// Prompts para LLM externo (Groq/Gemini/OpenAI) ou interno MineraAI
const hooksPrompt = `Você é um copywriter viral BR. Produto/tema: "${title}" (${platform}). Gere 5 hooks curtos (máx 12 palavras) para vídeos curtos, um por linha, sem numeração.`;
const labPrompt = `Analise este vídeo para replicação viral: "${title}". Responda em JSON com chaves: formato_detectado, hook_detectado, hipoteses_virais (array 3 itens), plano_replicacao (array 3 itens). PT-BR.`;

return [{ json: { item_id, video, title, platform, hooksPrompt, labPrompt, callback_url: `${$env.MINERAAI_URL}/api/curation/items/${item_id}/enrich`, token: $env.N8N_TOKEN || body.token || '' } }];

// Mescla resultados de hooks + lab
const prep = $('Preparar Prompts').first().json;
const hooksData = $('MineraAI · Gerar Hooks').first().json;
const labData = $input.first().json;

const hooks = (hooksData.hooks || []).map(h => typeof h === 'string' ? h : h.hook).slice(0,5);
const analise = labData;

const enrich = {
  hooks,
  analise,
  tags_sugeridas: [...(prep.video.hashtags || []), '#viral', '#curadoria', `#${prep.platform}`].slice(0,8),
  titulo_sugerido: `${prep.title.slice(0,60)} — versão curada`,
  notas_ia: `Outlier ${analise.outlier_score || '?'} · ${analise.veredito || ''} · Formato: ${analise.formato_detectado || ''}`,
  extra: { enriched_by: 'n8n', engine_hooks: hooksData.engine, engine_lab: labData.engine }
};

return [{ json: { item_id: prep.item_id, callback_url: prep.callback_url, token: prep.token, enrich } }];

// Opcional: gerar legenda + título SEO automaticamente
const prep = $('Preparar Prompts').first().json;
const enrich = $('Mesclar Enriquecimento').first().json.enrich;
return [{ json: { item_id: prep.item_id, title: prep.title, hooks: enrich.hooks, analise: enrich.analise } }];
